'use client';

import React, {
  useState,
  useRef,
  useEffect,
  useCallback,
  Children,
  cloneElement,
  isValidElement,
  type ReactNode,
} from 'react';
import {
  motion,
  useScroll,
  useSpring,
  useTransform,
  useMotionValueEvent,
  MotionValue,
} from 'framer-motion';
import { cn } from '../../lib/utils';

export interface CurvedCarouselCardWrapperProps {
  index?: number;
  virtualIndex?: MotionValue<number>;
  stepX?: number;
  curvatureY?: number;
  isMobile?: boolean;
  isActive?: boolean;
  onSelect?: (index: number) => void;
  children?: ReactNode;
  className?: string;
}

export const CurvedCarouselCardWrapper: React.FC<CurvedCarouselCardWrapperProps> = ({
  index = 0,
  virtualIndex,
  stepX = 360,
  curvatureY = 56,
  isMobile = false,
  isActive = false,
  onSelect,
  children,
  className,
}) => {
  const fallbackMotionValue = new MotionValue(0);
  const delta = useTransform(virtualIndex ?? fallbackMotionValue, (v: number) => index - v);

  const x = useTransform(delta, (d: number) => d * stepX);
  const y = useTransform(
    delta,
    (d: number) => Math.pow(Math.abs(d), 1.55) * curvatureY
  );
  const rotate = useTransform(
    delta,
    (d: number) => Math.max(-14, Math.min(14, d * (isMobile ? 5 : 7)))
  );
  const scale = useTransform(
    delta,
    (d: number) => Math.max(0.74, 1.05 - Math.abs(d) * (isMobile ? 0.12 : 0.14))
  );
  const opacity = useTransform(
    delta,
    (d: number) => Math.max(0, 1 - Math.pow(Math.abs(d) / (isMobile ? 2.5 : 2.4), 1.8))
  );
  const zIndex = useTransform(delta, (d: number) =>
    Math.round(50 - Math.abs(d) * 10)
  );

  return (
    <motion.div
      style={{ x, y, rotate, scale, opacity, zIndex }}
      onClick={() => onSelect?.(index)}
      className={cn(
        'absolute w-[82vw] max-w-[290px] sm:max-w-[340px] md:max-w-[380px] cursor-pointer will-change-transform select-none',
        isActive ? 'pointer-events-auto' : 'pointer-events-auto hover:brightness-110',
        className
      )}
    >
      {children}
    </motion.div>
  );
};

export interface CurvedCarouselProps extends React.HTMLAttributes<HTMLDivElement> {
  children: ReactNode[];
  header?: ReactNode;
  footerTrailing?: ReactNode;
  activeCurveColor?: string;
  showIndicators?: boolean;
  stageHeightClassName?: string;
  onActiveChange?: (index: number) => void;
  className?: string;
}

export const CurvedCarousel: React.FC<CurvedCarouselProps> = ({
  children,
  header,
  footerTrailing,
  activeCurveColor = '#C0A06C',
  showIndicators = true,
  stageHeightClassName = 'h-[380px] sm:h-[460px] md:h-[500px]',
  onActiveChange,
  className,
  ...props
}) => {
  const [activeIndex, setActiveIndex] = useState<number>(0);
  const [windowWidth, setWindowWidth] = useState<number>(1200);

  const containerRef = useRef<HTMLDivElement>(null);
  const touchStartX = useRef<number | null>(null);

  const childArray = Children.toArray(children);
  const totalCards = childArray.length;

  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const isMobile = windowWidth < 768;

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ['start start', 'end end'],
  });

  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 260,
    damping: 30,
    mass: 0.35,
  });

  const virtualIndex = useTransform(
    smoothProgress,
    [0, 1],
    [0, Math.max(0, totalCards - 1)]
  );

  useMotionValueEvent(virtualIndex, 'change', (latest: number) => {
    const nextIdx = Math.min(totalCards - 1, Math.max(0, Math.round(latest)));
    if (nextIdx !== activeIndex) {
      setActiveIndex(nextIdx);
      onActiveChange?.(nextIdx);
    }
  });

  const scrollToIndex = useCallback(
    (targetIndex: number) => {
      if (!containerRef.current || totalCards <= 1) return;
      const rect = containerRef.current.getBoundingClientRect();
      const containerTop = window.scrollY + rect.top;
      const scrollableDistance =
        containerRef.current.offsetHeight - window.innerHeight;
      const targetScroll =
        containerTop + (targetIndex / (totalCards - 1)) * scrollableDistance;

      window.scrollTo({
        top: targetScroll,
        behavior: 'smooth',
      });

      setActiveIndex(targetIndex);
      onActiveChange?.(targetIndex);
    },
    [totalCards, onActiveChange]
  );

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStartX.current === null) return;
    const touchEndX = e.changedTouches[0].clientX;
    const diff = touchStartX.current - touchEndX;

    if (Math.abs(diff) > 40) {
      if (diff > 0 && activeIndex < totalCards - 1) {
        scrollToIndex(activeIndex + 1);
      } else if (diff < 0 && activeIndex > 0) {
        scrollToIndex(activeIndex - 1);
      }
    }
    touchStartX.current = null;
  };

  const stepX = isMobile
    ? Math.min(270, windowWidth * 0.74)
    : Math.min(420, Math.max(340, windowWidth * 0.28));
  const curvatureY = isMobile ? 22 : 56;

  return (
    <div
      ref={containerRef}
      className={cn('relative min-h-[300vh] sm:min-h-[340vh] w-full bg-[#0E0E0E]', className)}
      {...(props as any)}
    >
      <div
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
        className="sticky top-0 h-[100dvh] max-h-[100dvh] w-full flex flex-col justify-between overflow-hidden select-none pt-16 sm:pt-24 pb-4 sm:pb-8 px-4 sm:px-8 md:px-12 border-t border-[#1F1F1F]"
      >
        {header && <div className="w-full max-w-7xl mx-auto z-20">{header}</div>}

        <div className="relative w-full flex-1 flex items-center justify-center overflow-visible my-auto">
          <svg
            className="absolute inset-x-0 top-1/2 -translate-y-1/2 w-full h-[280px] sm:h-[340px] pointer-events-none overflow-visible"
            viewBox="0 0 1200 300"
            preserveAspectRatio="none"
          >
            <defs>
              <linearGradient id="easyUiCurveGrad" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor={activeCurveColor} stopOpacity="0" />
                <stop offset="25%" stopColor={activeCurveColor} stopOpacity="0.35" />
                <stop offset="50%" stopColor={activeCurveColor} stopOpacity="0.8" />
                <stop offset="75%" stopColor={activeCurveColor} stopOpacity="0.35" />
                <stop offset="100%" stopColor={activeCurveColor} stopOpacity="0" />
              </linearGradient>
              <radialGradient id="easyUiCenterGlow" cx="50%" cy="40%" r="45%">
                <stop offset="0%" stopColor={activeCurveColor} stopOpacity="0.12" />
                <stop offset="100%" stopColor={activeCurveColor} stopOpacity="0" />
              </radialGradient>
            </defs>

            <ellipse cx="600" cy="120" rx="380" ry="120" fill="url(#easyUiCenterGlow)" />
            <path
              d="M 0,270 Q 600,10 1200,270"
              fill="none"
              stroke={activeCurveColor}
              strokeWidth="6"
              strokeOpacity="0.1"
            />
            <path
              d="M 0,270 Q 600,10 1200,270"
              fill="none"
              stroke="url(#easyUiCurveGrad)"
              strokeWidth="1.75"
              strokeDasharray="6 8"
            />
          </svg>

          <div className={cn('relative w-full flex items-center justify-center', stageHeightClassName)}>
            {childArray.map((child, idx) => {
              const isItemActive = idx === activeIndex;

              return (
                <CurvedCarouselCardWrapper
                  key={idx}
                  index={idx}
                  virtualIndex={virtualIndex}
                  stepX={stepX}
                  curvatureY={curvatureY}
                  isMobile={isMobile}
                  isActive={isItemActive}
                  onSelect={(targetIdx) => scrollToIndex(targetIdx)}
                >
                  {isValidElement(child)
                    ? cloneElement(child, {
                        isActive: isItemActive,
                      } as Partial<unknown>)
                    : child}
                </CurvedCarouselCardWrapper>
              );
            })}
          </div>
        </div>

        <div className="w-full max-w-7xl mx-auto z-20 flex flex-col sm:flex-row items-center justify-between gap-4 pt-3 border-t border-[#1F1F1F]">
          {showIndicators ? (
            <div className="text-xs font-mono tracking-widest text-neutral-400">
              <span className="text-white font-semibold">{String(activeIndex + 1).padStart(2, '0')}</span>
              <span className="mx-1.5 opacity-40">/</span>
              <span>{String(totalCards).padStart(2, '0')}</span>
            </div>
          ) : (
            <div />
          )}

          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => activeIndex > 0 && scrollToIndex(activeIndex - 1)}
                disabled={activeIndex === 0}
                aria-label="Previous item"
                className="p-2 rounded-lg border border-[#262626] bg-[#141414] text-neutral-300 hover:text-white hover:border-[#383838] disabled:opacity-30 disabled:pointer-events-none transition-colors"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="m15 18-6-6 6-6" />
                </svg>
              </button>
              <button
                type="button"
                onClick={() => activeIndex < totalCards - 1 && scrollToIndex(activeIndex + 1)}
                disabled={activeIndex === totalCards - 1}
                aria-label="Next item"
                className="p-2 rounded-lg border border-[#262626] bg-[#141414] text-neutral-300 hover:text-white hover:border-[#383838] disabled:opacity-30 disabled:pointer-events-none transition-colors"
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="m9 18 6-6-6-6" />
                </svg>
              </button>
            </div>

            {footerTrailing}
          </div>
        </div>
      </div>
    </div>
  );
};
